    public void launchIntegratedServer(String p_launchIntegratedServer_1_, String p_launchIntegratedServer_2_, WorldSettings p_launchIntegratedServer_3_) {
        FMLClientHandler.instance().startIntegratedServer(p_launchIntegratedServer_1_, p_launchIntegratedServer_2_, p_launchIntegratedServer_3_);
        this.loadWorld(null);
        System.gc();
        ISaveHandler isavehandler = this.saveLoader.getSaveLoader(p_launchIntegratedServer_1_, false);
        WorldInfo worldinfo = isavehandler.loadWorldInfo();
        if (worldinfo == null && p_launchIntegratedServer_3_ != null) {
            worldinfo = new WorldInfo(p_launchIntegratedServer_3_, p_launchIntegratedServer_1_);
            isavehandler.saveWorldInfo(worldinfo);
        }
        if (p_launchIntegratedServer_3_ == null) {
            p_launchIntegratedServer_3_ = new WorldSettings(worldinfo);
        }
        try {
            this.theIntegratedServer = new IntegratedServer(this, p_launchIntegratedServer_1_, p_launchIntegratedServer_2_, p_launchIntegratedServer_3_);
            this.theIntegratedServer.startServerThread();
            this.integratedServerIsRunning = true;
        }
        catch (Throwable throwable) {
            CrashReport crashreport = CrashReport.makeCrashReport(throwable, "Starting integrated server");
            CrashReportCategory crashreportcategory = crashreport.makeCategory("Starting integrated server");
            crashreportcategory.addCrashSection("Level ID", p_launchIntegratedServer_1_);
            crashreportcategory.addCrashSection("Level Name", p_launchIntegratedServer_2_);
            throw new ReportedException(crashreport);
        }
        this.loadingScreen.displaySavingString(I18n.format("menu.loadingLevel", new Object[0]));
        while (!this.theIntegratedServer.serverIsInRunLoop()) {
            if (!StartupQuery.check()) {
                this.loadWorld(null);
                this.displayGuiScreen(null);
                return;
            }
            String s = this.theIntegratedServer.getUserMessage();
            if (s != null) {
                this.loadingScreen.displayLoadingString(I18n.format(s, new Object[0]));
            } else {
                this.loadingScreen.displayLoadingString("");
            }
            try {
                Thread.sleep(200L);
            }
            catch (InterruptedException crashreport) {}
        }
        this.displayGuiScreen(null);
        SocketAddress socketaddress = this.theIntegratedServer.getNetworkSystem().addLocalEndpoint();
        NetworkManager networkmanager = NetworkManager.provideLocalClient(socketaddress);
        networkmanager.setNetHandler(new NetHandlerLoginClient(networkmanager, this, null));
        networkmanager.sendPacket(new C00Handshake(47, socketaddress.toString(), 0, EnumConnectionState.LOGIN, true));
        GameProfile gameProfile = this.getSession().getProfile();
        if (!this.getSession().hasCachedProperties()) {
            gameProfile = this.sessionService.fillProfileProperties(gameProfile, true);
            this.getSession().setProperties(gameProfile.getProperties());
        }
        networkmanager.sendPacket(new C00PacketLoginStart(gameProfile));
        this.myNetworkManager = networkmanager;
    }

