    public void renderItemModelForEntity(ItemStack p_renderItemModelForEntity_1_, EntityLivingBase p_renderItemModelForEntity_2_, ItemCameraTransforms.TransformType p_renderItemModelForEntity_3_) {
        if (p_renderItemModelForEntity_1_ != null && p_renderItemModelForEntity_2_ != null) {
            IBakedModel ibakedmodel = this.itemModelMesher.getItemModel(p_renderItemModelForEntity_1_);
            if (p_renderItemModelForEntity_2_ instanceof EntityPlayer) {
                EntityPlayer entityplayer = (EntityPlayer)p_renderItemModelForEntity_2_;
                Item item = p_renderItemModelForEntity_1_.getItem();
                ModelResourceLocation modelresourcelocation = null;
                if (item == Items.fishing_rod && entityplayer.fishEntity != null) {
                    modelresourcelocation = new ModelResourceLocation("fishing_rod_cast", "inventory");
                } else if (item == Items.bow && entityplayer.getItemInUse() != null) {
                    int i = p_renderItemModelForEntity_1_.getMaxItemUseDuration() - entityplayer.getItemInUseCount();
                    if (i >= 18) {
                        modelresourcelocation = new ModelResourceLocation("bow_pulling_2", "inventory");
                    } else if (i > 13) {
                        modelresourcelocation = new ModelResourceLocation("bow_pulling_1", "inventory");
                    } else if (i > 0) {
                        modelresourcelocation = new ModelResourceLocation("bow_pulling_0", "inventory");
                    }
                } else {
                    modelresourcelocation = item.getModel(p_renderItemModelForEntity_1_, entityplayer, entityplayer.getItemInUseCount());
                }
                if (modelresourcelocation != null) {
                    ibakedmodel = this.itemModelMesher.getModelManager().getModel(modelresourcelocation);
                }
            }
            this.renderItemModelTransform(p_renderItemModelForEntity_1_, ibakedmodel, p_renderItemModelForEntity_3_);
        }
    }

    protected void renderItemModelTransform(ItemStack p_renderItemModelTransform_1_, IBakedModel p_renderItemModelTransform_2_, ItemCameraTransforms.TransformType p_renderItemModelTransform_3_) {
        this.textureManager.bindTexture(TextureMap.locationBlocksTexture);
        this.textureManager.getTexture(TextureMap.locationBlocksTexture).setBlurMipmap(false, false);
        this.preTransform(p_renderItemModelTransform_1_);
        GlStateManager.enableRescaleNormal();
        GlStateManager.alphaFunc(516, 0.1f);
        GlStateManager.enableBlend();
        GlStateManager.tryBlendFuncSeparate(770, 771, 1, 0);
        GlStateManager.pushMatrix();
        p_renderItemModelTransform_2_ = ForgeHooksClient.handleCameraTransforms(p_renderItemModelTransform_2_, p_renderItemModelTransform_3_);
        this.renderItem(p_renderItemModelTransform_1_, p_renderItemModelTransform_2_);
        GlStateManager.cullFace(1029);
        GlStateManager.popMatrix();
        GlStateManager.disableRescaleNormal();
        GlStateManager.disableBlend();
        this.textureManager.bindTexture(TextureMap.locationBlocksTexture);
        this.textureManager.getTexture(TextureMap.locationBlocksTexture).restoreLastBlurMipmap();
    }

