    public void preparePlayer(EntityPlayerMP p_preparePlayer_1_, WorldServer p_preparePlayer_2_) {
        WorldServer worldserver = p_preparePlayer_1_.getServerForPlayer();
        if (p_preparePlayer_2_ != null) {
            p_preparePlayer_2_.getPlayerManager().removePlayer(p_preparePlayer_1_);
        }
        worldserver.getPlayerManager().addPlayer(p_preparePlayer_1_);
        worldserver.theChunkProviderServer.loadChunk((int)p_preparePlayer_1_.posX >> 4, (int)p_preparePlayer_1_.posZ >> 4);
    }

