    public void playerLoggedOut(EntityPlayerMP p_playerLoggedOut_1_) {
        FMLCommonHandler.instance().firePlayerLoggedOut(p_playerLoggedOut_1_);
        p_playerLoggedOut_1_.triggerAchievement(StatList.leaveGameStat);
        this.writePlayerData(p_playerLoggedOut_1_);
        WorldServer worldserver = p_playerLoggedOut_1_.getServerForPlayer();
        if (p_playerLoggedOut_1_.ridingEntity != null) {
            worldserver.removePlayerEntityDangerously(p_playerLoggedOut_1_.ridingEntity);
            logger.debug("removing player mount");
        }
        worldserver.removeEntity(p_playerLoggedOut_1_);
        worldserver.getPlayerManager().removePlayer(p_playerLoggedOut_1_);
        this.playerEntityList.remove(p_playerLoggedOut_1_);
        UUID uuid = p_playerLoggedOut_1_.getUniqueID();
        EntityPlayerMP entityplayermp = this.uuidToPlayerMap.get(uuid);
        if (entityplayermp == p_playerLoggedOut_1_) {
            this.uuidToPlayerMap.remove(uuid);
            this.playerStatFiles.remove(uuid);
        }
        ChunkIOExecutor.adjustPoolSize(this.getCurrentPlayerCount());
        this.sendPacketToAllPlayers(new S38PacketPlayerListItem(S38PacketPlayerListItem.Action.REMOVE_PLAYER, p_playerLoggedOut_1_));
    }

    public String allowUserToConnect(SocketAddress p_allowUserToConnect_1_, GameProfile p_allowUserToConnect_2_) {
        if (this.bannedPlayers.isBanned(p_allowUserToConnect_2_)) {
            UserListBansEntry userlistbansentry = (UserListBansEntry)this.bannedPlayers.getEntry(p_allowUserToConnect_2_);
            String s1 = "You are banned from this server!\nReason: " + userlistbansentry.getBanReason();
            if (userlistbansentry.getBanEndDate() != null) {
                s1 = s1 + "\nYour ban will be removed on " + dateFormat.format(userlistbansentry.getBanEndDate());
            }
            return s1;
        }
        if (!this.canJoin(p_allowUserToConnect_2_)) {
            return "You are not white-listed on this server!";
        }
        if (this.bannedIPs.isBanned(p_allowUserToConnect_1_)) {
            IPBanEntry ipbanentry = this.bannedIPs.getBanEntry(p_allowUserToConnect_1_);
            String s = "Your IP address is banned from this server!\nReason: " + ipbanentry.getBanReason();
            if (ipbanentry.getBanEndDate() != null) {
                s = s + "\nYour ban will be removed on " + dateFormat.format(ipbanentry.getBanEndDate());
            }
            return s;
        }
        return this.playerEntityList.size() >= this.maxPlayers && !this.bypassesPlayerLimit(p_allowUserToConnect_2_) ? "The server is full!" : null;
    }

    public EntityPlayerMP createPlayerForUser(GameProfile p_createPlayerForUser_1_) {
        UUID uuid = EntityPlayer.getUUID(p_createPlayerForUser_1_);
        ArrayList list = Lists.newArrayList();
        for (int i = 0; i < this.playerEntityList.size(); ++i) {
            EntityPlayerMP entityplayermp = this.playerEntityList.get(i);
            if (!entityplayermp.getUniqueID().equals(uuid)) continue;
            list.add(entityplayermp);
        }
        EntityPlayerMP entityplayermp2 = this.uuidToPlayerMap.get(p_createPlayerForUser_1_.getId());
        if (entityplayermp2 != null && !list.contains(entityplayermp2)) {
            list.add(entityplayermp2);
        }
        for (EntityPlayerMP entityplayermp1 : list) {
            entityplayermp1.playerNetServerHandler.kickPlayerFromServer("You logged in from another location");
        }
        ItemInWorldManager iteminworldmanager = this.mcServer.isDemo() ? new DemoWorldManager(this.mcServer.worldServerForDimension(0)) : new ItemInWorldManager(this.mcServer.worldServerForDimension(0));
        return new EntityPlayerMP(this.mcServer, this.mcServer.worldServerForDimension(0), p_createPlayerForUser_1_, iteminworldmanager);
    }

    public EntityPlayerMP recreatePlayerEntity(EntityPlayerMP p_recreatePlayerEntity_1_, int p_recreatePlayerEntity_2_, boolean p_recreatePlayerEntity_3_) {
        WorldServer world = this.mcServer.worldServerForDimension(p_recreatePlayerEntity_2_);
        if (world == null) {
            p_recreatePlayerEntity_2_ = 0;
        } else if (!world.provider.canRespawnHere()) {
            p_recreatePlayerEntity_2_ = world.provider.getRespawnDimension(p_recreatePlayerEntity_1_);
        }
        p_recreatePlayerEntity_1_.getServerForPlayer().getEntityTracker().removePlayerFromTrackers(p_recreatePlayerEntity_1_);
        p_recreatePlayerEntity_1_.getServerForPlayer().getEntityTracker().untrackEntity(p_recreatePlayerEntity_1_);
        p_recreatePlayerEntity_1_.getServerForPlayer().getPlayerManager().removePlayer(p_recreatePlayerEntity_1_);
        this.playerEntityList.remove(p_recreatePlayerEntity_1_);
        this.mcServer.worldServerForDimension(p_recreatePlayerEntity_1_.dimension).removePlayerEntityDangerously(p_recreatePlayerEntity_1_);
        BlockPos blockpos = p_recreatePlayerEntity_1_.getBedLocation(p_recreatePlayerEntity_2_);
        boolean flag = p_recreatePlayerEntity_1_.isSpawnForced(p_recreatePlayerEntity_2_);
        p_recreatePlayerEntity_1_.dimension = p_recreatePlayerEntity_2_;
        ItemInWorldManager iteminworldmanager = this.mcServer.isDemo() ? new DemoWorldManager(this.mcServer.worldServerForDimension(p_recreatePlayerEntity_1_.dimension)) : new ItemInWorldManager(this.mcServer.worldServerForDimension(p_recreatePlayerEntity_1_.dimension));
        EntityPlayerMP entityplayermp = new EntityPlayerMP(this.mcServer, this.mcServer.worldServerForDimension(p_recreatePlayerEntity_1_.dimension), p_recreatePlayerEntity_1_.getGameProfile(), iteminworldmanager);
        entityplayermp.playerNetServerHandler = p_recreatePlayerEntity_1_.playerNetServerHandler;
        entityplayermp.clonePlayer(p_recreatePlayerEntity_1_, p_recreatePlayerEntity_3_);
        entityplayermp.dimension = p_recreatePlayerEntity_2_;
        entityplayermp.setEntityId(p_recreatePlayerEntity_1_.getEntityId());
        entityplayermp.setCommandStats(p_recreatePlayerEntity_1_);
        WorldServer worldserver = this.mcServer.worldServerForDimension(p_recreatePlayerEntity_1_.dimension);
        this.setPlayerGameTypeBasedOnOther(entityplayermp, p_recreatePlayerEntity_1_, worldserver);
        if (blockpos != null) {
            BlockPos blockpos1 = EntityPlayer.getBedSpawnLocation(this.mcServer.worldServerForDimension(p_recreatePlayerEntity_1_.dimension), blockpos, flag);
            if (blockpos1 != null) {
                entityplayermp.setLocationAndAngles((float)blockpos1.getX() + 0.5f, (float)blockpos1.getY() + 0.1f, (float)blockpos1.getZ() + 0.5f, 0.0f, 0.0f);
                entityplayermp.setSpawnPoint(blockpos, flag);
            } else {
                entityplayermp.playerNetServerHandler.sendPacket(new S2BPacketChangeGameState(0, 0.0f));
            }
        }
        worldserver.theChunkProviderServer.loadChunk((int)entityplayermp.posX >> 4, (int)entityplayermp.posZ >> 4);
        while (!worldserver.getCollidingBoundingBoxes(entityplayermp, entityplayermp.getEntityBoundingBox()).isEmpty() && entityplayermp.posY < 256.0) {
            entityplayermp.setPosition(entityplayermp.posX, entityplayermp.posY + 1.0, entityplayermp.posZ);
        }
        entityplayermp.playerNetServerHandler.sendPacket(new S07PacketRespawn(entityplayermp.dimension, entityplayermp.worldObj.getDifficulty(), entityplayermp.worldObj.getWorldInfo().getTerrainType(), entityplayermp.theItemInWorldManager.getGameType()));
        BlockPos blockpos2 = worldserver.getSpawnPoint();
        entityplayermp.playerNetServerHandler.setPlayerLocation(entityplayermp.posX, entityplayermp.posY, entityplayermp.posZ, entityplayermp.rotationYaw, entityplayermp.rotationPitch);
        entityplayermp.playerNetServerHandler.sendPacket(new S05PacketSpawnPosition(blockpos2));
        entityplayermp.playerNetServerHandler.sendPacket(new S1FPacketSetExperience(entityplayermp.experience, entityplayermp.experienceTotal, entityplayermp.experienceLevel));
        this.updateTimeAndWeatherForPlayer(entityplayermp, worldserver);
        worldserver.getPlayerManager().addPlayer(entityplayermp);
        worldserver.spawnEntityInWorld(entityplayermp);
        this.playerEntityList.add(entityplayermp);
        this.uuidToPlayerMap.put(entityplayermp.getUniqueID(), entityplayermp);
        entityplayermp.addSelfToInternalCraftingInventory();
        entityplayermp.setHealth(entityplayermp.getHealth());
        FMLCommonHandler.instance().firePlayerRespawnEvent(entityplayermp);
        return entityplayermp;
    }

