    public final Item setRegistryName(String p_setRegistryName_1_) {
        String prefix;
        if (this.getRegistryName() != null) {
            throw new IllegalStateException("Attempted to set registry name on block with exisiting registry name! New: " + p_setRegistryName_1_ + " Old: " + this.getRegistryName());
        }
        int index = p_setRegistryName_1_.lastIndexOf(58);
        String oldPrefix = index == -1 ? "" : p_setRegistryName_1_.substring(0, index);
        p_setRegistryName_1_ = index == -1 ? p_setRegistryName_1_ : p_setRegistryName_1_.substring(index + 1);
        ModContainer mc = Loader.instance().activeModContainer();
        String string = prefix = mc == null ? "minecraft" : mc.getModId();
        if (!oldPrefix.equals(prefix) && oldPrefix.length() > 0) {
            FMLLog.bigWarning("Dangerous alternative prefix %s for name %s, invalid registry invocation/invalid name?", oldPrefix, p_setRegistryName_1_);
            prefix = oldPrefix;
        }
        this.registryName = new ResourceLocation(prefix, p_setRegistryName_1_);
        return this;
    }

    public final Item setRegistryName(ResourceLocation p_setRegistryName_1_) {
        return this.setRegistryName(p_setRegistryName_1_.toString());
    }

    public final Item setRegistryName(String p_setRegistryName_1_, String p_setRegistryName_2_) {
        return this.setRegistryName(p_setRegistryName_1_ + ":" + p_setRegistryName_2_);
    }

    public final String getRegistryName() {
        if (this.delegate.getResourceName() != null) {
            return this.delegate.getResourceName().toString();
        }
        return this.registryName != null ? this.registryName.toString() : null;
    }

