    public static void setCustomStateMapper(Block block, IStateMapper mapper) {
        customStateMappers.put(block.delegate, mapper);
    }

    public static void onRegisterAllBlocks(BlockModelShapes shapes) {
        for (Map.Entry<RegistryDelegate<Block>, IStateMapper> e : customStateMappers.entrySet()) {
            shapes.registerBlockWithStateMapper(e.getKey().get(), e.getValue());
        }
    }

    public static void setCustomModelResourceLocation(Item item, int metadata, ModelResourceLocation model) {
        customModels.put((Pair<RegistryDelegate<Item>, Integer>)Pair.of(item.delegate, (Object)metadata), model);
        ModelBakery.registerItemVariants((Item)item, (ResourceLocation[])new ModelResourceLocation[]{model});
    }

    public static void setCustomMeshDefinition(Item item, ItemMeshDefinition meshDefinition) {
        customMeshDefinitions.put(item.delegate, meshDefinition);
    }

    public static void setBucketModelDefinition(Item item) {
        ModelLoader.setCustomMeshDefinition(item, new ItemMeshDefinition(){

            @Override
            public ModelResourceLocation getModelLocation(ItemStack stack) {
                return ModelDynBucket.LOCATION;
            }
        });
        ModelBakery.registerItemVariants((Item)item, (ResourceLocation[])new ModelResourceLocation[]{ModelDynBucket.LOCATION});
    }

    public static void onRegisterItems(ItemModelMesher mesher) {
        for (Map.Entry<RegistryDelegate<Item>, ItemMeshDefinition> entry : customMeshDefinitions.entrySet()) {
            mesher.register(entry.getKey().get(), entry.getValue());
        }
        for (Map.Entry<RegistryDelegate<Item>, Object> entry : customModels.entrySet()) {
            mesher.register((Item)((RegistryDelegate)((Pair)entry.getKey()).getLeft()).get(), (Integer)((Pair)entry.getKey()).getRight(), (ModelResourceLocation)entry.getValue());
        }
    }

