    public static int getSkyBlendColour(World world, BlockPos center) {
        if (center.getX() == skyX && center.getZ() == skyZ && skyInit) {
            return skyRGBMultiplier;
        }
        skyInit = true;
        GameSettings settings = Minecraft.getMinecraft().gameSettings;
        int[] ranges = ForgeModContainer.blendRanges;
        int distance = 0;
        if (settings.fancyGraphics && settings.renderDistanceChunks >= 0 && settings.renderDistanceChunks < ranges.length) {
            distance = ranges[settings.renderDistanceChunks];
        }
        int r = 0;
        int g = 0;
        int b = 0;
        int divider = 0;
        for (int x = -distance; x <= distance; ++x) {
            for (int z = -distance; z <= distance; ++z) {
                BlockPos pos = center.add(x, 0, z);
                BiomeGenBase biome = world.getBiomeGenForCoords(pos);
                int colour = biome.getSkyColorByTemp(biome.getFloatTemperature(pos));
                r += (colour & 0xFF0000) >> 16;
                g += (colour & 0xFF00) >> 8;
                b += colour & 0xFF;
                ++divider;
            }
        }
        int multiplier = (r / divider & 0xFF) << 16 | (g / divider & 0xFF) << 8 | b / divider & 0xFF;
        skyX = center.getX();
        skyZ = center.getY();
        skyRGBMultiplier = multiplier;
        return skyRGBMultiplier;
    }

    public static void renderMainMenu(GuiMainMenu gui, FontRenderer font, int width, int height) {
        String line;
        ForgeVersion.Status status = ForgeVersion.getStatus();
        if (status == ForgeVersion.Status.BETA || status == ForgeVersion.Status.BETA_OUTDATED) {
            line = I18n.format("forge.update.beta.1", new Object[]{EnumChatFormatting.RED, EnumChatFormatting.RESET});
            gui.drawString(font, line, (width - font.getStringWidth(line)) / 2, 4 + 0 * (font.FONT_HEIGHT + 1), -1);
            line = I18n.format("forge.update.beta.2", new Object[0]);
            gui.drawString(font, line, (width - font.getStringWidth(line)) / 2, 4 + 1 * (font.FONT_HEIGHT + 1), -1);
        }
        line = null;
        switch (status) {
            case OUTDATED: 
            case BETA_OUTDATED: {
                line = I18n.format("forge.update.newversion", ForgeVersion.getTarget());
                break;
            }
        }
        if (line != null) {
            gui.drawString(font, line, width - font.getStringWidth(line) - 2, height - 2 * (font.FONT_HEIGHT + 1), -1);
        }
    }

